package docs

import (
	"os"
	"testing"
)

// The constants must be byte-identical to the fixtures generated by the Python
// reference implementation.
func TestTemplatesMatchFixtures(t *testing.T) {
	tests := []struct {
		name    string
		fixture string
		got     string
	}{
		{"spec template", "../../testdata/python_vault/templates/spec.md", SpecTemplate},
		{"decision template", "../../testdata/python_vault/templates/decision.md", DecisionTemplate},
		{"vault readme", "../../testdata/python_vault/README.md", VaultReadme},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			want, err := os.ReadFile(tt.fixture)
			if err != nil {
				t.Fatalf("read fixture: %v", err)
			}
			if tt.got != string(want) {
				t.Errorf("constant is not byte-identical to %s\ngot  %q\nwant %q", tt.fixture, tt.got, want)
			}
		})
	}
}
